package org.marketreview.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
/** ui(Context) must run on the host UI thread; main verifies parser/model only, never device UI. */
public final class ScenarioToolsScreenChecks {
 private static void need(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static JSONObject raw(String module,JSONObject input)throws JSONException{
  JSONObject def=ScenarioToolsScreen.contract().getJSONArray("tools").getJSONObject(Arrays.asList(ScenarioTools.MODULES).indexOf(module)),raw=new JSONObject();JSONArray fields=def.getJSONArray("fields");
  for(int i=0;i<fields.length();i++){JSONObject f=fields.getJSONObject(i);String k=f.getString("key"),kind=f.getString("kind");if("records".equals(kind)){JSONArray rows=new JSONArray(),source=input.optJSONArray(k);if(source!=null)for(int j=0;j<source.length();j++){JSONObject cells=new JSONObject(),r=source.getJSONObject(j);JSONArray columns=f.getJSONArray("columns");for(int c=0;c<columns.length();c++){String col=columns.getString(c);cells.put(col,r.has(col)&&!r.isNull(col)?r.get(col).toString():"");}rows.put(cells);}raw.put(k,rows);}else if("sequence".equals(kind)){List<String> xs=new ArrayList<>();JSONArray source=input.optJSONArray(k);if(source!=null)for(int j=0;j<source.length();j++)xs.add(source.get(j).toString());raw.put(k,String.join(",",xs));}else raw.put(k,input.get(k).toString());}return raw;
 }
 public static JSONObject state(String module,JSONObject raw)throws JSONException{return new JSONObject().put("schema","scenario-drafts/v1").put("module",module).put("drafts",new JSONObject().put(module,raw));}
 public static void ui(Context context,JSONObject fixtures)throws Exception{
  ScenarioToolsScreen p=new ScenarioToolsScreen(context);JSONArray cases=fixtures.getJSONArray("cases");for(String module:ScenarioTools.MODULES){JSONObject input=null;for(int i=0;i<cases.length();i++)if(module.equals(cases.getJSONObject(i).getString("name")))input=cases.getJSONObject(i).getJSONObject("input");need(input!=null,"fixture "+module);p.restoreState(state(module,raw(module,input)));((Button)p.findViewWithTag("scenarioCalculate")).performClick();need(((TextView)p.findViewWithTag("scenarioStatus")).getText().toString().startsWith("已按"),"calculate "+module);need(!((TextView)p.findViewWithTag("scenarioResult")).getText().toString().isEmpty(),"empty "+module);}
  p.restoreState(state("target",raw("target",new JSONObject().put("initialCapital",10000).put("targetCapital",20000).put("years",5).put("monthlyContribution",0))));((Button)p.findViewWithTag("scenarioCalculate")).performClick();((EditText)p.findViewWithTag("scenario_initialCapital")).setText("12000");need(((TextView)p.findViewWithTag("scenarioResult")).getText().length()==0,"stale result");((Button)p.findViewWithTag("scenarioSave")).performClick();ScenarioToolsScreen reopened=new ScenarioToolsScreen(context);need(((EditText)reopened.findViewWithTag("scenario_initialCapital")).getText().toString().equals("12000"),"save reopen");need(((TextView)reopened.findViewWithTag("scenarioResult")).getText().length()==0,"auto calculate");
  p.restoreState(state("risk",new JSONObject().put("cashBalance","1000").put("positions",new JSONArray())));((Button)p.findViewWithTag("scenario_add_positions")).performClick();LinearLayout rows=p.findViewWithTag("scenario_positions"),row=(LinearLayout)rows.getChildAt(0);((EditText)row.findViewWithTag("code")).setText("SH:stock:600000");((EditText)row.findViewWithTag("marketValue")).setText("2000");((Button)p.findViewWithTag("scenarioCalculate")).performClick();need(((TextView)p.findViewWithTag("scenarioResult")).getText().toString().contains("3000"),"record calculate");((EditText)row.findViewWithTag("marketValue")).setText("bad");((Button)p.findViewWithTag("scenarioCalculate")).performClick();need(((TextView)p.findViewWithTag("scenarioStatus")).getText().toString().contains("失败"),"invalid record");((Button)row.findViewWithTag("scenario_remove_positions")).performClick();need(rows.getChildCount()==0,"remove record");((Button)p.findViewWithTag("scenarioClear")).performClick();((Button)p.findViewWithTag("scenarioSave")).performClick();
 }
 public static void main(String[] args)throws Exception{
  JSONObject fixtures=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),StandardCharsets.UTF_8));JSONArray cases=fixtures.getJSONArray("cases");int done=0;
  for(String module:ScenarioTools.MODULES){JSONObject input=null;for(int i=0;i<cases.length();i++)if(module.equals(cases.getJSONObject(i).getString("name")))input=cases.getJSONObject(i).getJSONObject("input");need(input!=null,"fixture "+module);JSONObject raw=raw(module,input);ScenarioToolsScreen.validateState(state(module,raw));JSONObject parsed=ScenarioToolsScreen.parseDraft(module,raw);need(ScenarioTools.evaluate(module,parsed).getJSONObject("result").length()>0,"result "+module);done++;}
  try{ScenarioToolsScreen.parseDraft("stagedAverage",new JSONObject().put("cash","10000").put("prices","10,,8").put("weights","50,50").put("lotSize","100"));throw new AssertionError("empty sequence accepted");}catch(IllegalArgumentException expected){}
  try{ScenarioToolsScreen.validateState(state("risk",new JSONObject().put("positions",true)));throw new AssertionError("malformed state accepted");}catch(IllegalArgumentException expected){}
  JSONObject risk=ScenarioToolsScreen.parseDraft("risk",new JSONObject().put("positions",new JSONArray().put(new JSONObject().put("code","SZ:stock:000001").put("id","SZ:stock:000001").put("market","SZ").put("marketValue",""))).put("cashBalance","0"));need(!risk.getJSONArray("positions").getJSONObject(0).has("marketValue"),"missing coerced zero");need(risk.getJSONArray("positions").getJSONObject(0).getString("id").equals("SZ:stock:000001"),"identity lost");try{ScenarioTools.evaluate("risk",risk);throw new AssertionError("missing valuation accepted");}catch(IllegalArgumentException expected){}
  int iid=0;for(int n=1;n<=8;n++)for(int k=1;k<=n+1;k++)for(double win:new double[]{0,25,50,100}){double probability=0;for(int bits=0;bits<(1<<n);bits++){int run=0;boolean hit=false;double weight=1;for(int i=0;i<n;i++){boolean loss=(bits&(1<<i))!=0;run=loss?run+1:0;hit|=run>=k;weight*=loss?1-win/100:win/100;}if(hit)probability+=weight;}JSONObject r=ScenarioTools.evaluate("lossRun",new JSONObject().put("winRatePercent",win).put("trialCount",n).put("streakLength",k)).getJSONObject("result");need(Math.abs(r.getDouble("atLeastOneStreakProbabilityPercent")-probability*100)<1e-6,"IID enumeration");iid++;}
  System.out.println("Android parser/model: "+done+" tool forms, missing/invalid/state/identity and "+iid+" independent IID cases GREEN; device UI NOT RUN");
 }
}
